import re
d=open('BQT_v1_pages.txt',encoding='utf-8',errors='replace').read().split('\f')
def fa2int(s): return int(s.translate(str.maketrans('۰۱۲۳۴۵۶۷۸۹','0123456789')))
out=[]
for i,leaf in enumerate(d):
    head='\n'.join(leaf.split('\n')[:3])
    for m in re.findall(r'[۰-۹]{2,3}',head):
        n=fa2int(m)
        if 1<=n<=600 and abs(i-n-215)<12:
            out.append((i,n,i-n)); break
for t in out: print(t)
